mapper.select:
select
    tl.*,
    u.user_name as userName,
    s.name as supplierName
from
    t_purchase_list tl
    left join t_user u on tl.user_id = u.id
    left join t_supplier s on tl.supplier_id = s.id


        tl.purchase_number = #{purchaseListQuery.purchaseNumber}


        and tl.supplier_id = #{purchaseListQuery.supplierId}


        and tl.state = #{purchaseListQuery.state}


        and purchase_date >= #{purchaseListQuery.startDate}


        and purchase_date <= #{purchaseListQuery.endDate}


order by purchase_number asc
